import type { CaseInput } from "../../lib/types";
import type { LabPanels } from "../../lib/domain/labs/labTypes";

export type LabWorkflowQaCase = {
  id: string;
  title: string;
  input: CaseInput;
  labs: LabPanels;
  expectedLeadAfter?: string;
  expectedTop3AfterIncludes?: string[];
  expectedLabFeatures?: string[];
  expectedSafetyWarningIds?: string[];
  expectedModifierDiagnoses?: string[];
  forbiddenLeadAfter?: string[];
  notes: string;
};

const baseInput: CaseInput = {
  age: "",
  sex: "",
  presentingComplaint: "",
  history: "",
  pmh: "",
  meds: "",
  social: "",
  keyPositives: "",
  keyNegatives: "",
  observations: "",
  leadDiagnosis: "",
  otherDifferentials: "",
  dangerousDiagnoses: "",
};

function input(overrides: Partial<CaseInput>): CaseInput {
  return { ...baseInput, ...overrides };
}

